export type AssetCycleProvenance = 'REAL' | 'PROXY' | 'PENDING';
export type AssetCycleState = '价格强势' | '趋势改善' | '区间震荡' | '初步反弹' | '价格走弱' | '观察不足' | '待接入';
type Observation = {
  weekId: string;
  value: number;
  sourceObservationDate: string;
  providerAvailableAt: string;
  snapshotAvailableAt: string;
  status: 'OK';
};
type ConnectedAsset = {
  assetId: string;
  ticker: string;
  name: string;
  provenance: 'REAL' | 'PROXY';
  valueType: string;
  adjustmentMethod: 'QFQ' | 'NONE' | 'NOT_APPLICABLE';
  interpretationMode: 'PRICE_HIGHER_IS_STRONG';
  sourceOwner: string;
  provider: string;
  sourceUrl: string;
  proxyReason?: string;
  knownBasisRisk?: string;
  observations: Observation[];
};
export type AssetCycleDataset = {
  schemaVersion: '1.3';
  algorithmVersion: 'weekly-asof-v4';
  stateModelVersion: 'self-percentile-v1';
  generatedAt: string;
  snapshotRule: string;
  assets: ConnectedAsset[];
};
export type AssetCycleHealth = {
  schemaVersion: '1.0';
  generatedAt: string;
  status: 'OK' | 'DATA ERROR';
  blockingCoreAdvice: false;
  researchUnavailable: boolean;
  summary: string;
  lastSuccessfulGeneratedAt: string | null;
  dataGeneratedAt: string | null;
  coverage: { catalog: number; connected: number; real: number; proxy: number; pending: number };
  issues: Array<{ type: string; label: string; details: string }>;
};

