const catalogIds = new Set(ASSET_CYCLE_CATALOG.map((item) => item.id));

export function parseAssetCycleDataset(input: unknown): AssetCycleDataset {
  const data = input as AssetCycleDataset;
  const generatedAt = Date.parse(data?.generatedAt);
  if (data?.schemaVersion !== '1.3' || data?.algorithmVersion !== 'weekly-asof-v4' || data?.stateModelVersion !== 'self-percentile-v1' || !Number.isFinite(generatedAt) || !Array.isArray(data.assets) || data.assets.length === 0) throw new Error('资产周期数据契约不兼容');
  const ids = new Set<string>();
  for (const asset of data.assets) {
    if (!asset?.assetId || !catalogIds.has(asset.assetId) || ids.has(asset.assetId) || !asset.ticker || !asset.name || !['REAL','PROXY'].includes(asset.provenance) || !['QFQ','NONE','NOT_APPLICABLE'].includes(asset.adjustmentMethod) || asset.interpretationMode !== 'PRICE_HIGHER_IS_STRONG' || !asset.sourceUrl || !Array.isArray(asset.observations) || asset.observations.length < 100) {
      throw new Error(`资产周期序列不完整：${asset?.assetId ?? 'unknown'}`);
    }
    ids.add(asset.assetId);
    let lastWeek = '';
    for (const observation of asset.observations) {
      const providerAvailableAt = Date.parse(observation.providerAvailableAt);
      const snapshotAvailableAt = Date.parse(observation.snapshotAvailableAt);
      if (!/^\d{4}-W\d{2}$/.test(observation.weekId) || observation.weekId <= lastWeek || !Number.isFinite(observation.value) || observation.value <= 0 || observation.status !== 'OK' || !Number.isFinite(providerAvailableAt) || !Number.isFinite(snapshotAvailableAt) || snapshotAvailableAt < providerAvailableAt || snapshotAvailableAt > generatedAt) {
        throw new Error(`资产周期包含不可用观测：${asset.assetId}/${observation.weekId}`);
      }
      lastWeek = observation.weekId;
    }
  }
  return data;
}

export function parseAssetCycleHealth(input: unknown): AssetCycleHealth {
  const health = input as AssetCycleHealth;
  if (health?.schemaVersion !== '1.0' || !['OK', 'DATA ERROR'].includes(health.status) || health.blockingCoreAdvice !== false || typeof health.researchUnavailable !== 'boolean' || !Number.isFinite(Date.parse(health.generatedAt)) || !health.coverage || health.coverage.catalog !== ASSET_CYCLE_CATALOG.length || !Array.isArray(health.issues)) {
    throw new Error('资产周期健康数据契约不兼容');
  }
  return health;
}

const signed = (value: number | null, digits = 1, suffix = '%') => value == null ? '—' : `${value >= 0 ? '+' : ''}${value.toFixed(digits)}${suffix}`;

export type AssetCycleSnapshot = ReturnType<typeof snapshot>;

function snapshot(definition: Definition, data: AssetCycleDataset, weeks: string[], weekIndex: number) {
  const connected = data.assets.find((asset) => asset.assetId === definition.id);
  const byWeek = new Map(connected?.observations.map((item) => [item.weekId, item]));
  const series: Array<number|null> = connected ? weeks.map((week) => byWeek.get(week)?.value ?? null) : weeks.map(() => null);
  const current = series[weekIndex] ?? null;
  const rateAt = (endpoint: number, distance: number) => endpoint >= distance && series[endpoint] != null && series[endpoint-distance] != null ? (series[endpoint]! / series[endpoint-distance]! - 1) * 100 : null;
  const m4 = rateAt(weekIndex, 4), m13 = rateAt(weekIndex, 13), m26 = rateAt(weekIndex, 26), change = rateAt(weekIndex, 1);
  // 只用当前观测周之前已完成的13周收益样本，当前值不参与自身分位的参考集。
  const history: number[] = [];
  for (let endpoint = 13; endpoint < weekIndex; endpoint += 1) {
    const value = rateAt(endpoint, 13);
    if (value != null) history.push(value);
  }
  const reference = history.slice(-104);
  const percentile = m13 != null && reference.length >= 52 ? reference.filter((value) => value <= m13).length / reference.length * 100 : null;
  let state: AssetCycleState = connected ? '观察不足' : '待接入';
  if (percentile != null) {
    if (percentile >= 80) state = '价格强势';
    else if (percentile >= 60) state = '趋势改善';
    else if (percentile <= 20) state = '价格走弱';
    else if (percentile < 40 && (m4 ?? 0) > 0) state = '初步反弹';
    else state = '区间震荡';
  }
  let legacyState = '中性';
  if (m13 != null && m4 != null) {
    if (m13 > 5) legacyState = '强势';
    else if (m13 > 1.5 && m4 > m13 / 3) legacyState = '趋势增强';
    else if (m13 < -5) legacyState = '风险升温';
    else if (m4 > 1.2 && m13 < 0) legacyState = '趋势反转';
  }
  const observation = connected ? byWeek.get(weeks[weekIndex]!) : undefined;
  return { series, current, change, m4, m13, m26, percentile, referenceCount: reference.length, state, legacyState, provenance: (connected?.provenance ?? 'PENDING') as AssetCycleProvenance, connected, observation };
}

export function calculateAssetCycleSnapshot(assetId: string, data: AssetCycleDataset, weeks: string[], weekIndex: number): AssetCycleSnapshot {
  const definition = ASSET_CYCLE_CATALOG.find((item) => item.id === assetId);
  if (!definition) throw new Error(`未知资产周期位置：${assetId}`);
  return snapshot(definition, data, weeks, weekIndex);
}

function sparkline(values: Array<number|null>, state: AssetCycleState): string {
  const valid = values.filter((value): value is number => value != null);
  if (valid.length < 2) return `<span class="cycle-no-data">${state === '待接入' ? '等待稳定公开序列' : '当周无可用趋势'}</span>`;
  const min=Math.min(...valid), max=Math.max(...valid), range=max-min||1;
  const points=values.map((value,index)=>value==null?'':`${(index/Math.max(1,values.length-1)*100).toFixed(2)},${(36-(value-min)/range*32).toFixed(2)}`).filter(Boolean).join(' ');
  const tone=state==='价格走弱'?'#ef7076':state==='价格强势'||state==='趋势改善'?'#79d6a0':state==='初步反弹'?'#efbf6b':'#d9e1dc';
  return `<svg class="cycle-spark" viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true"><line x1="0" y1="36" x2="100" y2="36"/><polyline points="${points}" style="stroke:${tone}"/></svg>`;
}

