function healthBanner(health?: AssetCycleHealth): string {
  if (!health) return `<div class="cycle-health is-unknown"><strong>数据健康未单独校验</strong><span>页面仍按数据契约验证；该研究模块不影响核心风险建议。</span></div>`;
  const last = health.lastSuccessfulGeneratedAt ? new Date(health.lastSuccessfulGeneratedAt).toLocaleString('zh-CN', { hour12: false }) : '无';
  return `<div class="cycle-health ${health.status === 'DATA ERROR' ? 'is-error' : 'is-ok'}"><strong>${health.status === 'DATA ERROR' ? 'ASSET CYCLE DATA ERROR' : '资产周期数据正常'}</strong><span>${escapeHtml(health.summary)}</span><small>最后成功：${escapeHtml(last)} · 不阻断核心风险评分与目标仓位</small></div>`;
}

