function matchesFilter(filter: string, provenance: AssetCycleProvenance, state: AssetCycleState): boolean {
  if (filter === '全部资产') return true;
  if (filter === '已接入数据') return provenance !== 'PENDING';
  if (filter === '仅真实数据') return provenance === 'REAL';
  if (filter === '仅代理数据') return provenance === 'PROXY';
  if (filter === '待接入') return provenance === 'PENDING';
  return filter === state;
}

