    const assets=ASSET_CYCLE_CATALOG.map((definition)=>({definition, point:snapshot(definition,data,weeks,index), previous:index>0?snapshot(definition,data,weeks,index-1):null}));
    const available=assets.filter((item)=>item.point.provenance!=='PENDING'&&item.point.current!=null);
